import {cabinet,rect,circle,text,ring} from './cabinet.js';
export function dropFour(b,col,who){for(let r=5;r>=0;r--)if(!b[r*7+col]){b[r*7+col]=who;return r;}return -1;}
export function fourWinner(b){for(let i=0;i<42;i++){if(!b[i])continue;const x=i%7,y=Math.floor(i/7);for(const [dx,dy] of [[1,0],[0,1],[1,1],[-1,1]]){const cells=[i];for(let n=1;n<4;n++){const xx=x+dx*n,yy=y+dy*n;if(xx<0||xx>=7||yy>=6||b[yy*7+xx]!==b[i])break;cells.push(yy*7+xx);}if(cells.length===4)return {who:b[i],cells};}}return null;}
function evaluate(b){let value=0;for(let r=0;r<6;r++)value+=b[r*7+3]===2?4:b[r*7+3]===1?-4:0;for(let i=0;i<42;i++)for(const [dx,dy] of [[1,0],[0,1],[1,1],[-1,1]]){const x=i%7,y=Math.floor(i/7),xx=x+dx*3,yy=y+dy*3;if(xx<0||xx>=7||yy>=6)continue;const cells=Array.from({length:4},(_,n)=>b[(y+dy*n)*7+x+dx*n]),ai=cells.filter(v=>v===2).length,human=cells.filter(v=>v===1).length;if(!human)value+=[0,1,8,55,5000][ai];if(!ai)value-=[0,1,9,70,5000][human];}return value;}
function search(b,depth,who,alpha=-Infinity,beta=Infinity){const winner=fourWinner(b);if(winner)return winner.who===2?10000+depth:-10000-depth;if(!depth||b.every(Boolean))return evaluate(b);let best=who===2?-Infinity:Infinity;for(const col of [3,2,4,1,5,0,6]){if(b[col])continue;const copy=[...b];dropFour(copy,col,who);const v=search(copy,depth-1,3-who,alpha,beta);best=who===2?Math.max(best,v):Math.min(best,v);if(who===2)alpha=Math.max(alpha,best);else beta=Math.min(beta,best);if(beta<=alpha)break;}return best;}
export function chooseFour(b){let best=-Infinity,choice=-1;for(const col of [3,2,4,1,5,0,6]){if(b[col])continue;const copy=[...b];dropFour(copy,col,2);const v=search(copy,3,1);if(v>best){best=v;choice=col;}}return choice;}
export function createFour(mount,api){const q=cabinet(mount,api,{accent:'#ffbe80',height:440}),c=q.c;let b=Array(42).fill(0),turn=1,wait=0,cursor=3,last=-1,win=null,moves=0;
 function place(col){if(!q.active||col<0||col>6)return;const row=dropFour(b,col,turn);if(row<0){q.sound('blocked');return;}last=row*7+col;q.sound('place',turn===1?0:5);if(turn===1)moves++;win=fourWinner(b);if(win){q.add(win.who===1?Math.max(100,1200-moves*25):0);q.finish(win.who===1?'Four. For you.':'The machine connected.',win.who===1?`A clean connection in ${moves} turns.`:'Try a center opening and watch the diagonals.',win.who===1);return;}if(b.every(Boolean)){q.finish('Perfectly balanced.','A full-board draw. Shall we settle this?');return;}turn=3-turn;wait=.65;}
 return {start(){b=Array(42).fill(0);turn=1;wait=0;last=-1;win=null;moves=0;q.start();},tap(p){p=q.local(p);if(turn===1&&p.y>35&&p.y<383){cursor=Math.floor((p.x-19)/46);place(cursor);}},direction(d){cursor=Math.max(0,Math.min(6,cursor+(d==='left'?-1:d==='right'?1:0)));if(d==='down'&&turn===1)place(cursor);},action(){if(turn===1)place(cursor);},tick(dt){q.frame(dt,dt=>{if(turn===2){wait-=dt;if(wait<=0)place(chooseFour(b));}},()=>{q.header('YOU ●  vs  CPU ●',turn===1?'YOUR TURN':'THINKING…');circle(c,19+cursor*46+23,53,9,'#ffbe80');rect(c,15,74,330,285,'#233b55',16);b.forEach((v,i)=>{const x=42+i%7*46,y=99+Math.floor(i/7)*46;circle(c,x,y+2,19,'#0d192a');circle(c,x,y,18,v===1?'#ffbe80':v===2?'#b9acff':'#13263d');if(i===last)ring(c,x,y,12,'#ffffff88');if(win?.cells.includes(i))ring(c,x,y,21,'#fff',3);});text(c,'Connect four in any direction.',180,393,15,'#d3deeb');q.footer('Tap a column to drop your disc.');});},destroy:q.destroy};}
